/**
 * Toggle: turns the object into an on/off switch.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { Component } from "../core";

export interface ToggleParams {
  /** Whether it starts in the "on" state. */
  on: boolean;
  /** Opacity shown while off (relative to the object's own alpha; 1 = unchanged). */
  offAlpha: number;
}

/**
 * Makes an object behave like an on/off switch: tapping it flips the state and dims it when off.
 * React to changes with `target.on("toggle", (on: boolean) => …)`, or read `isOn()`.
 */
export class Toggle extends Component<ToggleParams> {
  static readonly componentName = "Toggle";
  static readonly defaults: ToggleParams = { on: true, offAlpha: 0.4 };

  private on = true;
  private baseAlpha = 1;

  private readonly onTap = (): void => {
    this.on = !this.on;
    this.refresh();
    this.target.emit("toggle", this.on);
  };

  attach(): void {
    this.baseAlpha = this.target.alpha;
    this.target.eventMode = "static";
    this.target.cursor = "pointer";
    this.target.on("pointertap", this.onTap);
  }

  apply(): void {
    this.on = this.params.on;
    this.refresh();
  }

  detach(): void {
    this.target.off("pointertap", this.onTap);
    this.target.alpha = this.baseAlpha;
  }

  /** The current state. */
  isOn(): boolean {
    return this.on;
  }

  private refresh(): void {
    this.target.alpha = this.on
      ? this.baseAlpha
      : this.baseAlpha * this.params.offAlpha;
  }
}
